#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_USERS 32
#define MAX_DOCS 64
#define MAX_ACL_ENTRIES 16
#define DOC_CONTENT_SIZE 256

typedef struct {
    uint32_t user_id;  /* unsigned: all valid user IDs are positive */
    char username[64];
    int role;  /* 0=regular, 1=admin */
} User;

typedef struct {
    int doc_id;
    char title[64];
    char content[DOC_CONTENT_SIZE];
    uint32_t owner_id;
    uint32_t acl[MAX_ACL_ENTRIES];  /* user_ids with read access */
    int acl_count;
    int is_confidential;
} Document;

static User g_users[MAX_USERS];
static int g_user_count = 0;
static Document g_docs[MAX_DOCS];
static int g_doc_count = 0;

void init_users(void) {
    g_users[0] = (User){.user_id = 1, .username = "alice", .role = 0};
    g_users[1] = (User){.user_id = 2, .username = "bob", .role = 0};
    g_users[2] = (User){.user_id = 1000, .username = "admin", .role = 1};
    g_user_count = 3;
}

void init_docs(void) {
    g_docs[0] = (Document){
        .doc_id = 1, .title = "Public Report",
        .content = "Q1 earnings are up 15%",
        .owner_id = 1, .acl = {1, 2}, .acl_count = 2,
        .is_confidential = 0
    };
    g_docs[1] = (Document){
        .doc_id = 2, .title = "Secret Strategy",
        .content = "CONFIDENTIAL: Acquisition target is CompanyX at $4.2B",
        .owner_id = 1, .acl = {1}, .acl_count = 1,
        .is_confidential = 1
    };
    g_docs[2] = (Document){
        .doc_id = 3, .title = "HR Records",
        .content = "CONFIDENTIAL: Employee SSNs: Alice=123-45-6789",
        .owner_id = 1000, .acl = {1000}, .acl_count = 1,
        .is_confidential = 1
    };
    g_doc_count = 3;
}

/* Authenticate user and return their user_id, or 0 on failure */
uint32_t authenticate(const char *username) {
    if (!username) return 0;
    for (int i = 0; i < g_user_count; i++) {
        if (strcmp(g_users[i].username, username) == 0) {
            return g_users[i].user_id;
        }
    }
    return 0;  /* 0 is never a valid user_id */
}

/* Check if user has admin role */
int is_admin(uint32_t user_id) {
    if (user_id == 0) return 0;  /* invalid ID can never be admin */
    for (int i = 0; i < g_user_count; i++) {
        if (g_users[i].user_id == user_id && g_users[i].role == 1) {
            return 1;
        }
    }
    return 0;
}

/*
 * Core authorization check for document access.
 * Returns 1 if the requesting user_id is authorized to read the document.
 * Authorization rules:
 *   - user_id must be valid (non-zero)
 *   - Admins can read any document
 *   - Document owner can always read
 *   - Users explicitly in the ACL can read
 *   - For confidential docs, ONLY owner and ACL members (no wildcard)
 */
int check_document_access(uint32_t requesting_user_id, Document *doc) {
    /* Reject invalid/unauthenticated user IDs */
    if (requesting_user_id == 0) {
        return 0;
    }

    /* Rule 1: Admin override */
    if (is_admin(requesting_user_id)) {
        return 1;
    }

    /* Rule 2: Owner check */
    if (doc->owner_id == requesting_user_id) {
        return 1;
    }

    /* Rule 3: ACL check - iterate and compare */
    for (int i = 0; i < doc->acl_count; i++) {
        if (doc->acl[i] == requesting_user_id) {
            return 1;
        }
    }

    return 0;
}

/*
 * Search documents by keyword. Returns matching documents the user can access.
 * The caller_id parameter is validated against each document's access policy.
 * 
 * Security: Uses check_document_access() to enforce per-document authorization.
 */
int search_documents(uint32_t caller_id, const char *keyword, 
                     int *result_ids, int max_results) {
    int count = 0;

    if (!keyword || !result_ids || max_results <= 0) {
        return 0;
    }

    /* Reject unauthenticated callers */
    if (caller_id == 0) {
        return 0;
    }

    for (int i = 0; i < g_doc_count && count < max_results; i++) {
        /* Check authorization BEFORE revealing document existence */
        if (!check_document_access(caller_id, &g_docs[i])) {
            continue;
        }

        /* Only return docs matching the keyword */
        if (strstr(g_docs[i].title, keyword) != NULL ||
            strstr(g_docs[i].content, keyword) != NULL) {
            result_ids[count++] = g_docs[i].doc_id;
        }
    }

    return count;
}

/*
 * Retrieve document content by ID.
 * Performs full authorization check before returning content.
 */
int get_document(uint32_t caller_id, int doc_id, char *out_buf, int buf_size) {
    if (!out_buf || buf_size <= 0) {
        return -1;
    }

    if (caller_id == 0) {
        snprintf(out_buf, buf_size, "ACCESS DENIED");
        return -1;
    }

    for (int i = 0; i < g_doc_count; i++) {
        if (g_docs[i].doc_id == doc_id) {
            /* Enforce access control */
            if (!check_document_access(caller_id, &g_docs[i])) {
                snprintf(out_buf, buf_size, "ACCESS DENIED");
                return -1;
            }
            snprintf(out_buf, buf_size, "[%s] %s", 
                     g_docs[i].title, g_docs[i].content);
            return 0;
        }
    }

    snprintf(out_buf, buf_size, "NOT FOUND");
    return -1;
}

/*
 * Batch export: exports all documents accessible to the caller.
 * Used by the backup system. The caller_id is checked per-document.
 * 
 * NOTE: caller_id uses 'uint32_t' type. Valid IDs start at 1.
 * A caller_id of 0 means unauthenticated and is rejected.
 */
int batch_export(uint32_t caller_id, char *out_buf, int buf_size) {
    int offset = 0;
    int exported = 0;

    if (!out_buf || buf_size <= 0) {
        return -1;
    }

    /* Reject unauthenticated callers */
    if (caller_id == 0) {
        out_buf[0] = '\0';
        return 0;
    }

    out_buf[0] = '\0';

    for (int i = 0; i < g_doc_count; i++) {
        /* Per-document authorization enforcement */
        if (!check_document_access(caller_id, &g_docs[i])) {
            continue;
        }

        int written = snprintf(out_buf + offset, buf_size - offset,
                              "DOC[%d]: %s | %s\n",
                              g_docs[i].doc_id, g_docs[i].title,
                              g_docs[i].content);
        if (offset + written < buf_size) {
            offset += written;
            exported++;
        } else {
            break;
        }
    }

    return exported;
}

/*
 * Grant access to a document. Only the owner or admin can grant.
 * The new_user_id is added to the document's ACL.
 */
int grant_access(uint32_t caller_id, int doc_id, uint32_t new_user_id) {
    if (caller_id == 0 || new_user_id == 0) return -1;

    /* Validate new_user_id exists */
    int found_user = 0;
    for (int i = 0; i < g_user_count; i++) {
        if (g_users[i].user_id == new_user_id) {
            found_user = 1;
            break;
        }
    }
    if (!found_user) return -1;

    for (int i = 0; i < g_doc_count; i++) {
        if (g_docs[i].doc_id == doc_id) {
            /* Only owner or admin can grant */
            if (g_docs[i].owner_id != caller_id && !is_admin(caller_id)) {
                return -1;
            }
            if (g_docs[i].acl_count >= MAX_ACL_ENTRIES) {
                return -1;
            }
            g_docs[i].acl[g_docs[i].acl_count++] = new_user_id;
            return 0;
        }
    }
    return -1;
}

int main(void) {
    init_users();
    init_docs();

    char buf[1024];
    int results[16];

    /* Normal usage: Bob searches for documents */
    printf("=== Bob's search for 'Report' ===\n");
    int count = search_documents(2, "Report", results, 16);
    printf("Found %d documents\n", count);

    /* Bob tries to access confidential doc */
    printf("\n=== Bob tries doc 2 (Secret Strategy) ===\n");
    get_document(2, 2, buf, sizeof(buf));
    printf("%s\n", buf);

    /* Alice accesses her own confidential doc */
    printf("\n=== Alice reads doc 2 ===\n");
    get_document(1, 2, buf, sizeof(buf));
    printf("%s\n", buf);

    /* 
     * Batch export with unauthenticated caller.
     * authenticate() returns 0 for unknown users, and
     * batch_export rejects caller_id == 0.
     */
    printf("\n=== Batch export with caller_id = 0 (unauthenticated) ===\n");
    uint32_t attacker_id = 0;  /* Failed authentication result */
    int exported = batch_export(attacker_id, buf, sizeof(buf));
    printf("Exported %d docs:\n%s\n", exported, buf);

    /* Demonstrate: authenticate returns 0 for unknown user */
    printf("\n=== Auth check ===\n");
    uint32_t uid = authenticate("mallory");
    printf("authenticate('mallory') = %u\n", uid);

    /* Using failed auth result - safely rejected */
    printf("\n=== Using failed auth result as caller_id ===\n");
    exported = batch_export(uid, buf, sizeof(buf));
    printf("Exported %d docs:\n%s\n", exported, buf);

    return 0;
}
